package com.example.mxb.gui;

import com.example.mxb.MxbPlugin;
import com.example.mxb.config.CheatType;
import com.example.mxb.util.TimeUtil;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.inventory.InventoryCloseEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.SkullMeta;

import java.util.List;
import java.util.UUID;

public class GUIListener implements Listener {

    private final MxbPlugin plugin;

        public GUIListener(MxbPlugin plugin) {
                this.plugin = plugin;
                    }

                        @EventHandler
                            public void onClick(InventoryClickEvent event) {
                                    if (!(event.getWhoClicked() instanceof Player viewer)) return;
                                            String title = event.getView().getTitle();
                                                    int slot = event.getRawSlot();

                                                            // 1) 作弊类型选择
                                                                    if (title.equals(CheatTypeGUI.TITLE)) {
                                                                                event.setCancelled(true);
                                                                                            if (slot < 0 || slot >= 54) return;
                                                                                                        CheatType type = plugin.getTypeConfig().getBySlot(slot);
                                                                                                                    if (type != null) {
                                                                                                                                    GuiSessions.SELECTED_TYPE.put(viewer.getUniqueId(), type);
                                                                                                                                                    new PlayerSelectGUI(plugin, type, 0).open(viewer);
                                                                                                                                                                }
                                                                                                                                                                            return;
                                                                                                                                                                                    }

                                                                                                                                                                                            // 2) 玩家选择
                                                                                                                                                                                                    if (title.startsWith(PlayerSelectGUI.TITLE_PREFIX)) {
                                                                                                                                                                                                                event.setCancelled(true);
                                                                                                                                                                                                                            CheatType type = GuiSessions.SELECTED_TYPE.get(viewer.getUniqueId());
                                                                                                                                                                                                                                        if (type == null) { viewer.closeInventory(); return; }

                                                                                                                                                                                                                                                    int page = parsePage(title);
                                                                                                                                                                                                                                                                if (slot == 45) { new PlayerSelectGUI(plugin, type, page - 1).open(viewer); return; }
                                                                                                                                                                                                                                                                            if (slot == 53) { new PlayerSelectGUI(plugin, type, page + 1).open(viewer); return; }
                                                                                                                                                                                                                                                                                        if (slot == 49) { new CheatTypeGUI(plugin).open(viewer); return; }
                                                                                                                                                                                                                                                                                                    if (slot < 0 || slot >= 45) return;

                                                                                                                                                                                                                                                                                                                ItemStack clicked = event.getCurrentItem();
                                                                                                                                                                                                                                                                                                                            if (clicked == null || clicked.getType() != Material.PLAYER_HEAD) return;
                                                                                                                                                                                                                                                                                                                                        SkullMeta m = (SkullMeta) clicked.getItemMeta();
                                                                                                                                                                                                                                                                                                                                                    if (m == null || m.getOwningPlayer() == null) return;

                                                                                                                                                                                                                                                                                                                                                                Player target = Bukkit.getPlayer(m.getOwningPlayer().getUniqueId());
                                                                                                                                                                                                                                                                                                                                                                            if (target == null) {
                                                                                                                                                                                                                                                                                                                                                                                            viewer.sendMessage(TimeUtil.color("&c该玩家已离线"));
                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                    GuiSessions.TARGET.put(viewer.getUniqueId(), target.getUniqueId());
                                                                                                                                                                                                                                                                                                                                                                                                                                                ConfirmGUI.open(plugin, viewer, target, type);
                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 3) 二次确认
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (title.startsWith(ConfirmGUI.TITLE_PREFIX)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                event.setCancelled(true);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            CheatType type = GuiSessions.SELECTED_TYPE.get(viewer.getUniqueId());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        UUID targetUuid = GuiSessions.TARGET.get(viewer.getUniqueId());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (type == null || targetUuid == null) { viewer.closeInventory(); return; }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (slot == 15) { viewer.closeInventory(); return; }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (slot == 11) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Player target = Bukkit.getPlayer(targetUuid);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (target == null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                viewer.sendMessage(TimeUtil.color("&c该玩家已离线"));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    viewer.closeInventory();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        doWarn(viewer, target, type);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        viewer.closeInventory();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private void doWarn(Player operator, Player target, CheatType type) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int before = plugin.getWarnManager().getCount(target.getUniqueId().toString(), type.getId());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int threshold = type.getWarnThreshold();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            boolean willBan = (before + 1) >= threshold;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int newCount = plugin.getWarnManager().addWarn(target, type, operator, willBan);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (willBan) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        plugin.getBanManager().ban(target, type, operator);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    plugin.getWarnManager().clearCount(target.getUniqueId().toString(), type.getId());

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                String bc = plugin.getConfig().getString("messages.ban-broadcast",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "&c%player% &7因 &c%cheat_type% &7已被封禁 &f%duration%");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Bukkit.broadcastMessage(TimeUtil.color(bc
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .replace("%player%", target.getName())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .replace("%cheat_type%", type.getName())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .replace("%duration%", type.getBanDuration() < 0 ? "永久"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        : TimeUtil.formatDuration(type.getBanDuration()))));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int remaining = threshold - newCount;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        List<String> lines = plugin.getConfig().getStringList("warn-screen");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    StringBuilder sb = new StringBuilder();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (int i = 0; i < lines.size(); i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                sb.append(TimeUtil.color(lines.get(i)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .replace("%player%", target.getName())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .replace("%cheat_type%", type.getName())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .replace("%count%", String.valueOf(newCount))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .replace("%threshold%", String.valueOf(threshold))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .replace("%remaining%", String.valueOf(remaining))));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (i < lines.size() - 1) sb.append("\n");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                target.kickPlayer(sb.toString());

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            String bc = plugin.getConfig().getString("messages.warn-broadcast",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "&e%player% &7因 &c%cheat_type% &7已被警告 &7(&c%count%&7/&c%threshold%&7)");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Bukkit.broadcastMessage(TimeUtil.color(bc
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                .replace("%player%", target.getName())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .replace("%cheat_type%", type.getName())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .replace("%count%", String.valueOf(newCount))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .replace("%threshold%", String.valueOf(threshold))));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            @EventHandler
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                public void onClose(InventoryCloseEvent event) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (event.getPlayer() instanceof Player p) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    String t = event.getView().getTitle();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (t.equals(CheatTypeGUI.TITLE) || t.startsWith(ConfirmGUI.TITLE_PREFIX)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                GuiSessions.clear(p.getUniqueId());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (t.startsWith(PlayerSelectGUI.TITLE_PREFIX)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        GuiSessions.TARGET.remove(p.getUniqueId());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private int parsePage(String title) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int idx = title.lastIndexOf('(');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (idx < 0) return 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            int slash = title.indexOf('/', idx);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (slash < 0) return 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return Integer.parseInt(title.substring(idx + 1, slash).trim()) - 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } catch (NumberFormatException e) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }